// ตัวช่วยขอสิทธิ์ Etsy — ทำงาน 2 จังหวะผ่าน URL เดียวกัน
//   จังหวะ 1: เปิด URL เปล่า -> สร้างลิงก์ขออนุญาต (เก็บ code_verifier ไว้)
//   จังหวะ 2: Etsy ส่งกลับมาพร้อม ?code= -> แลกเป็น refresh token + หา shop_id + หมวดหมู่
// ทั้งสองจังหวะวิ่งผ่าน production webhook เท่านั้น static data จึงถูกบันทึกจริง
function sha256Bytes(msgBytes) {
  const K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  let h = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const l = msgBytes.length;
  const withPad = new Uint8Array(((l + 72) >> 6) << 6); // ปัดขึ้นเป็นทวีคูณของ 64 ที่ >= l+9
  withPad.set(msgBytes);
  withPad[l] = 0x80;
  const bitLen = l * 8;
  const dv = new DataView(withPad.buffer);
  dv.setUint32(withPad.length - 4, bitLen >>> 0, false);
  dv.setUint32(withPad.length - 8, Math.floor(bitLen / 4294967296), false);
  const w = new Uint32Array(64);
  const rr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let i = 0; i < withPad.length; i += 64) {
    for (let j = 0; j < 16; j++) w[j] = dv.getUint32(i + j * 4, false);
    for (let j = 16; j < 64; j++) {
      const s0 = rr(w[j-15],7) ^ rr(w[j-15],18) ^ (w[j-15] >>> 3);
      const s1 = rr(w[j-2],17) ^ rr(w[j-2],19) ^ (w[j-2] >>> 10);
      w[j] = (w[j-16] + s0 + w[j-7] + s1) >>> 0;
    }
    let [a,b,c,d,e,f,g,hh] = h;
    for (let j = 0; j < 64; j++) {
      const S1 = rr(e,6) ^ rr(e,11) ^ rr(e,25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (hh + S1 + ch + K[j] + w[j]) >>> 0;
      const S0 = rr(a,2) ^ rr(a,13) ^ rr(a,22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      hh = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    h = [(h[0]+a)>>>0,(h[1]+b)>>>0,(h[2]+c)>>>0,(h[3]+d)>>>0,(h[4]+e)>>>0,(h[5]+f)>>>0,(h[6]+g)>>>0,(h[7]+hh)>>>0];
  }
  const outBytes = new Uint8Array(32);
  const odv = new DataView(outBytes.buffer);
  h.forEach((v, i) => odv.setUint32(i * 4, v, false));
  return outBytes;
}
function b64url(bytes) {
  let s = '';
  for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
  return Buffer.from(s, 'latin1').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

const inp = $input.first().json;
const q = inp.query || {};
const store = $getWorkflowStaticData('global');

const esc = s => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const page = (title, bodyHtml, color) => ({
  html: '<!DOCTYPE html><html lang="th"><head><meta charset="utf-8">' +
    '<meta name="viewport" content="width=device-width,initial-scale=1">' +
    '<title>' + esc(title) + '</title><style>' +
    'body{font-family:-apple-system,Segoe UI,Roboto,"Noto Sans Thai",sans-serif;background:#f6f7f9;margin:0;padding:24px;color:#1c1e21}' +
    '.card{max-width:760px;margin:0 auto;background:#fff;border-radius:14px;padding:28px 32px;box-shadow:0 2px 14px rgba(0,0,0,.08)}' +
    'h1{font-size:22px;margin:0 0 6px;color:' + (color || '#1c1e21') + '}' +
    'p{line-height:1.7}code,pre{background:#f0f2f5;border-radius:8px;font-family:ui-monospace,Menlo,Consolas,monospace}' +
    'code{padding:2px 6px;font-size:13px;word-break:break-all}' +
    'pre{padding:14px;overflow-x:auto;font-size:13px;white-space:pre-wrap;word-break:break-all}' +
    '.btn{display:inline-block;background:#f1641e;color:#fff;text-decoration:none;padding:14px 28px;border-radius:24px;font-weight:700;margin:14px 0}' +
    'table{border-collapse:collapse;width:100%;margin-top:10px}' +
    'th,td{border:1px solid #ddd;padding:9px 11px;text-align:left;font-size:14px;vertical-align:top}' +
    'th{background:#f0f2f5;width:190px}.muted{color:#65676b;font-size:13px}' +
    '</style></head><body><div class="card">' + bodyHtml + '</div></body></html>',
});

// ---- ค่าตั้งต้น ----
const keystring = String(inp.etsy_keystring || '').trim();
let redirectUri = String(inp.redirect_uri || '').trim();
if (!redirectUri || /^YOUR_/i.test(redirectUri)) {
  const host = (inp.headers && (inp.headers['x-forwarded-host'] || inp.headers.host)) || '';
  redirectUri = 'https://' + host + '/webhook/etsy-auth';
}

if (!keystring || /^YOUR_/i.test(keystring)) {
  return [page('ยังไม่ได้ตั้งค่า', '<h1>⚠️ ยังไม่ได้กรอก Keystring</h1>' +
    '<p>เปิด workflow นี้ใน n8n แล้วดับเบิลคลิกโหนด <b>Etsy Auth Config</b> กรอกช่อง <code>etsy_keystring</code> ' +
    'ด้วย Keystring ของแอปจาก <b>etsy.com/developers</b> แล้วกด Save ก่อนครับ</p>', '#c9302c')];
}

const parse = r => { if (r && typeof r === 'object') return r; try { return JSON.parse(String(r)); } catch (e) { return {}; } };

/* ============ จังหวะ 2: Etsy ส่ง code กลับมา ============ */
if (q.code || q.error) {
  if (q.error) {
    return [page('ไม่ได้รับอนุญาต', '<h1>❌ Etsy ปฏิเสธการขอสิทธิ์</h1><p><code>' + esc(q.error) + ' ' +
      esc(q.error_description || '') + '</code></p><p>ลองเปิด URL นี้ใหม่แล้วกด <b>Grant access</b> ครับ</p>', '#c9302c')];
  }
  const verifier = store.etsy_code_verifier;
  if (!verifier) {
    return [page('ลิงก์หมดอายุ', '<h1>⚠️ ไม่พบรหัสลับของรอบนี้</h1>' +
      '<p>ลิงก์นี้อาจเป็นของรอบเก่า หรือ workflow ถูกปิด Active ระหว่างทาง</p>' +
      '<p>วิธีแก้: เปิด <code>' + esc(redirectUri) + '</code> ใหม่อีกครั้ง (แบบไม่มี ?code= ต่อท้าย) แล้วเริ่มใหม่ครับ</p>', '#c9302c')];
  }
  if (q.state && store.etsy_state && q.state !== store.etsy_state) {
    return [page('ลิงก์ไม่ตรงกัน', '<h1>⚠️ state ไม่ตรง</h1><p>น่าจะเป็นลิงก์เก่า — เปิด <code>' +
      esc(redirectUri) + '</code> ใหม่แล้วเริ่มอีกครั้งครับ</p>', '#c9302c')];
  }

  const form = 'grant_type=authorization_code' +
    '&client_id=' + encodeURIComponent(store.etsy_keystring || keystring) +
    '&redirect_uri=' + encodeURIComponent(store.etsy_redirect_uri || redirectUri) +
    '&code=' + encodeURIComponent(q.code) +
    '&code_verifier=' + encodeURIComponent(verifier);

  let tok = {}, lastErr = '';
  for (const url of ['https://openapi.etsy.com/v3/public/oauth/token', 'https://api.etsy.com/v3/public/oauth/token']) {
    try {
      tok = parse(await this.helpers.httpRequest({
        method: 'POST', url,
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: form, json: false, timeout: 30000,
      }));
      if (tok.access_token) break;
    } catch (e) {
      const b = (e && e.response && (e.response.body || e.response.data)) || '';
      lastErr = String((e && e.message) || e) + ' ' + (typeof b === 'string' ? b : JSON.stringify(b));
    }
  }
  if (!tok.access_token) {
    return [page('แลก token ไม่สำเร็จ', '<h1>❌ แลก token ไม่สำเร็จ</h1><pre>' + esc(lastErr.slice(0, 600)) +
      '</pre><p>ตรวจว่า Callback URL ในแอป Etsy ตรงกับ <code>' + esc(redirectUri) + '</code> เป๊ะๆ แล้วลองใหม่ครับ</p>', '#c9302c')];
  }

  store.etsy_refresh_token = tok.refresh_token;
  const auth = { 'x-api-key': keystring, 'Authorization': 'Bearer ' + tok.access_token };

  // ---- shop_id: ลองหลายทางแยกกัน ทางไหนพังก็ไปทางถัดไป ----
  // เลข user id ซ่อนอยู่หน้าจุดของ access token อยู่แล้ว (เช่น "1234567.xxxxx") ไม่ต้องเรียก API เพิ่ม
  let shopId = '', shopName = '', shopErrs = [];
  const userId = String(tok.access_token).split('.')[0];
  const tryGet = async (label, url, headers) => {
    if (shopId) return;
    try {
      const r = parse(await this.helpers.httpRequest({ url, headers, json: true, timeout: 30000 }));
      const s = r && r.shop_id ? r : ((r && r.results && r.results[0]) || {});
      if (s && s.shop_id) { shopId = String(s.shop_id); shopName = s.shop_name || ''; }
      else shopErrs.push(label + ': ไม่มี shop_id ในคำตอบ');
    } catch (e) {
      const b = (e && e.response && (e.response.body || e.response.data)) || '';
      shopErrs.push(label + ': ' + String((e && e.message) || e) + ' ' + (typeof b === 'string' ? b : JSON.stringify(b)));
    }
  };
  if (/^\d+$/.test(userId)) await tryGet('users/' + userId + '/shops', 'https://openapi.etsy.com/v3/application/users/' + userId + '/shops', auth);
  await tryGet('users/me', 'https://openapi.etsy.com/v3/application/users/me', auth);
  const wantShopName = String(inp.etsy_shop_name || '').trim();
  if (wantShopName) await tryGet('shops?shop_name', 'https://openapi.etsy.com/v3/application/shops?shop_name=' + encodeURIComponent(wantShopName), { 'x-api-key': keystring });
  const shopErr = shopErrs.join(' | ');

  // ---- หมวดหมู่ (taxonomy) ----
  let taxRows = '', taxErr = '';
  try {
    const tx = parse(await this.helpers.httpRequest({ url: 'https://openapi.etsy.com/v3/application/seller-taxonomy/nodes', headers: { 'x-api-key': keystring }, json: true, timeout: 90000 }));
    const all = [];
    const walk = (nodes, trail) => {
      for (const n of nodes || []) {
        const p = trail.concat(n.name);
        all.push({ id: n.id, name: n.name, path: p.join(' > ') });
        if (n.children && n.children.length) walk(n.children, p);
      }
    };
    walk(tx.results, []);
    if (!all.length) taxErr = 'Etsy ไม่ได้ส่งรายการหมวดหมู่กลับมา';
    // เรียงตามความเกี่ยวข้อง: ชื่อมีคำว่า coloring > เส้นทางมีคำว่า coloring > กระดาษ/ดิจิทัล
    const score = (x) => {
      if (/colou?ring/i.test(x.name)) return 3;
      if (/colou?ring/i.test(x.path)) return 2;
      if (/digital|printable|paper craft|party supplies > paper/i.test(x.path)) return 1;
      return 0;
    };
    const found = all.map(x => ({ ...x, s: score(x) })).filter(x => x.s > 0).sort((a, b) => b.s - a.s).slice(0, 12);
    taxRows = found.map(f => '<tr><th>' + f.id + '</th><td>' + esc(f.path) + '</td></tr>').join('');
  } catch (e) {
    const b = (e && e.response && (e.response.body || e.response.data)) || '';
    taxErr = String((e && e.message) || e) + ' ' + (typeof b === 'string' ? b : JSON.stringify(b));
  }
  if (!taxRows) {
    taxRows = '<tr><td colspan="2" class="muted">หาหมวดหมู่อัตโนมัติไม่ได้' + (taxErr ? ' (' + esc(taxErr.slice(0, 180)) + ')' : '') +
      '<br>วิธีหาเอง: ลองสร้างสินค้า 1 ชิ้นด้วยมือในร้าน เลือกหมวดที่ต้องการ แล้วดูเลข taxonomy_id ได้จากหน้ารายละเอียดสินค้า หรือเปิด ' +
      '<code>https://openapi.etsy.com/v3/application/seller-taxonomy/nodes</code> พร้อมส่ง header x-api-key</td></tr>';
  }

  return [page('สำเร็จ',
    '<h1>✅ เชื่อมต่อ Etsy สำเร็จ</h1>' +
    '<p>คัดลอก 3 ค่านี้ไปกรอกในโหนด <b>Config</b> ของ workflow หลัก (AI Coloring Book Factory) ครับ</p>' +
    '<table>' +
    '<tr><th>etsy_refresh_token</th><td><code>' + esc(tok.refresh_token) + '</code></td></tr>' +
    '<tr><th>etsy_shop_id</th><td><code>' + esc(shopId || '(หาไม่เจอ)') + '</code>' +
    (shopName ? ' <span class="muted">— ร้าน ' + esc(shopName) + '</span>' : '') +
    (!shopId ? '<div class="muted">' + (shopErr ? esc(shopErr.slice(0, 400)) + '<br>' : '') +
      '<b>วิธีแก้:</b> ดับเบิลคลิกโหนด <b>Etsy Auth Config</b> ในไฟล์นี้ กรอกช่อง <code>etsy_shop_name</code> ' +
      'ด้วยชื่อร้านของคุณ (ตัวที่อยู่หลัง etsy.com/shop/ เช่น <code>WuteArtStudio</code>) แล้ว Save + เปิด URL นี้ใหม่' +
      '<br>ถ้ายังไม่ได้เปิดร้าน Etsy ต้องเปิดร้านให้เสร็จก่อน</div>' : '') + '</td></tr>' +
    '<tr><th>user_id (ไว้อ้างอิง)</th><td><code>' + esc(userId) + '</code></td></tr>' +
    '<tr><th>etsy_keystring</th><td><code>' + esc(keystring) + '</code></td></tr>' +
    '</table>' +
    '<h1 style="font-size:17px;margin-top:26px">เลือก 1 อันใส่ etsy_taxonomy_id</h1><table>' + taxRows + '</table>' +
    '<p class="muted" style="margin-top:22px">⚠️ อย่าแชร์หน้านี้ให้ใคร — refresh_token คือกุญแจเข้าร้านของคุณ<br>' +
    'refresh_token มีอายุ 90 วัน แต่ workflow หลักจะต่ออายุให้เองทุกครั้งที่รัน<br>' +
    'เสร็จแล้วปิด Active ของ workflow ตัวช่วยนี้ได้เลย</p>', '#2e7d32')];
}

/* ============ จังหวะ 1: สร้างลิงก์ขออนุญาต ============ */
const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~';
let rnd;
try { rnd = new Uint8Array(43); crypto.getRandomValues(rnd); }
catch (e) { rnd = new Uint8Array(43); for (let i = 0; i < 43; i++) rnd[i] = Math.floor(Math.random() * 256); }
let verifier = '';
for (let i = 0; i < 43; i++) verifier += chars[rnd[i] % chars.length];

const bytes = new Uint8Array(verifier.length);
for (let i = 0; i < verifier.length; i++) bytes[i] = verifier.charCodeAt(i);
const challenge = b64url(sha256Bytes(bytes));
const state = 'cbf' + Date.now().toString(36);

store.etsy_code_verifier = verifier;
store.etsy_state = state;
store.etsy_keystring = keystring;
store.etsy_redirect_uri = redirectUri;

const scopes = 'listings_r listings_w shops_r';
const authUrl = 'https://www.etsy.com/oauth/connect' +
  '?response_type=code' +
  '&client_id=' + encodeURIComponent(keystring) +
  '&redirect_uri=' + encodeURIComponent(redirectUri) +
  '&scope=' + encodeURIComponent(scopes) +
  '&state=' + encodeURIComponent(state) +
  '&code_challenge=' + encodeURIComponent(challenge) +
  '&code_challenge_method=S256';

return [page('ขอสิทธิ์ Etsy',
  '<h1>🔑 เชื่อมต่อร้าน Etsy</h1>' +
  '<p>กดปุ่มด้านล่างเพื่อไปหน้าอนุญาตของ Etsy แล้วกด <b>Grant access</b> — เสร็จแล้วระบบจะพากลับมาที่หน้านี้พร้อมค่าที่ต้องใช้</p>' +
  '<p><a class="btn" href="' + esc(authUrl) + '">ไปหน้าอนุญาตของ Etsy →</a></p>' +
  '<p class="muted">Callback URL ที่ต้องตั้งไว้ในแอป Etsy ต้องตรงกับบรรทัดนี้เป๊ะๆ:<br><code>' + esc(redirectUri) + '</code></p>' +
  '<p class="muted">สิทธิ์ที่ขอ: ' + esc(scopes) + ' (ดู/สร้าง/แก้สินค้า และดูข้อมูลร้าน)</p>')];
